{"sql":"-- 2. Create table monthly_reports if not exists
CREATE TABLE IF NOT EXISTS employees.monthly_reports (
  report_id SERIAL PRIMARY KEY,
  report_date DATE NOT NULL,
  department_count INTEGER NOT NULL,
  total_employees INTEGER NOT NULL,
  avg_salary NUMERIC(15,2) NOT NULL,
  generated_at TIMESTAMPTZ DEFAULT now()
);

-- 2. Create stored procedure generate_monthly_report
CREATE OR REPLACE FUNCTION employees.generate_monthly_report(report_date DATE) RETURNS INTEGER AS $$
DECLARE
  v_department_count INTEGER;
  v_total_employees INTEGER;
  v_avg_salary NUMERIC(15,2);
  v_report_id INTEGER;
BEGIN
  -- Calculate department count
  SELECT COUNT(*) INTO v_department_count FROM employees.department;

  -- Calculate total active employees
  SELECT COUNT(DISTINCT de.employee_id) INTO v_total_employees
  FROM employees.department_employee de
  WHERE de.to_date = '9999-01-01';

  -- Calculate average current salary
  SELECT AVG(s.amount)::numeric(15,2) INTO v_avg_salary
  FROM employees.salary s
  WHERE s.to_date = '9999-01-01';

  -- Insert new report record
  INSERT INTO employees.monthly_reports (report_date, department_count, total_employees, avg_salary)
  VALUES (report_date, v_department_count, v_total_employees, v_avg_salary)
  RETURNING report_id INTO v_report_id;

  RETURN v_report_id;
END;
$$ LANGUAGE plpgsql;

-- 3. Create salary_alerts table if not exists
CREATE TABLE IF NOT EXISTS employees.salary_alerts (
  alert_id SERIAL PRIMARY KEY,
  employee_id BIGINT NOT NULL,
  salary_amount BIGINT NOT NULL,
  alert_date TIMESTAMPTZ DEFAULT now(),
  status VARCHAR(20) DEFAULT 'new'
);

-- 4. Create trigger and function for high_salary_alert
CREATE OR REPLACE FUNCTION employees.fn_high_salary_alert() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.amount > 120000 THEN
    INSERT INTO employees.salary_alerts (employee_id, salary_amount, alert_date, status)
    VALUES (NEW.employee_id, NEW.amount, now(), 'new');
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS high_salary_alert ON employees.salary;

CREATE TRIGGER high_salary_alert
AFTER INSERT ON employees.salary
FOR EACH ROW
EXECUTE FUNCTION employees.fn_high_salary_alert();"}

